Done := (Count = 3);

PrevTrigger := Trigger;

END_PROGRAM

PROGRAM dosing
VAR_INPUT
    Trigger : BOOL;
    Reset : BOOL;
END_VAR
VAR_OUTPUT
    Done : BOOL;
END_VAR
VAR
    Count : INT := 0;
    PrevTrigger : BOOL := FALSE;
END_VAR
VAR CONSTANT
    N : INT := 3;
END_VAR
BEGIN
    IF Reset THEN
        Count := 0;
        Done := FALSE;
    ELSE
        // Detect rising edge of Trigger
        IF Trigger AND NOT PrevTrigger THEN
            // Increment Count only if it has not reached N yet
            IF Count < N THEN
                Count := Count + 1;
            END_IF;
        END_IF;

        // Assert Done when Count reaches N
        IF Count = N THEN
            Done := TRUE;
        ELSE
            Done := FALSE;
        END_IF;
    END_IF;

    // Store current Trigger state for next scan's edge detection
    PrevTrigger := Trigger;
END_PROGRAM

